• رشا (السكرتيرة الخاصة): جلال كان مهددها بـ "وصل أمانة" كانت مضياه عليه لما استلمت عهدة اللاب توب الغالي، وكان بيرفض يرجعهولها وبيبتزها عشان متسبش الشغل.
